const i = $('Вхід: розширена команда').first().json;
const a = String(i.action || '').toLowerCase().trim();
const API = 'https://api.hetzner.cloud/v1';
let aux = API + '/locations';
if (a === 'list_ssh_keys') aux = API + '/ssh_keys?per_page=50';
if (a === 'create_from_snapshot') aux = API + '/images?type=snapshot&per_page=50';
return [{ json: { aux_url: aux } }];

const API = 'https://api.hetzner.cloud/v1';
const i = $('Вхід: розширена команда').first().json;
const action = String(i.action || '').toLowerCase().trim();
const serverQ = String(i.server || '').trim();
const target = String(i.target || '').trim();
const extra = String(i.extra || '').trim();
const confirmed = String(i.confirm || '').toLowerCase().trim() === 'yes';
const servers = $('Hetzner: список серверів').first().json.servers || [];

const KNOWN = ['server_info', 'rename', 'shutdown', 'reset', 'rebuild', 'enable_rescue', 'disable_rescue', 'reset_password', 'list_ssh_keys', 'add_ssh_key', 'server_metrics', 'cost_report', 'protect', 'unprotect', 'create_from_snapshot'];
const SERVER_ACTIONS = ['server_info', 'rename', 'shutdown', 'reset', 'rebuild', 'enable_rescue', 'disable_rescue', 'reset_password', 'server_metrics', 'protect', 'unprotect'];
const READ_ONLY = ['server_info', 'server_metrics'];
const NEEDS_CONFIRM = ['reset', 'rebuild', 'enable_rescue', 'reset_password', 'unprotect', 'create_from_snapshot'];

const aux = $input.first().json || {};
const res = (o) => [{ json: Object.assign({ action: action }, o) }];
const fail = (msg) => res({ skip: true, message: '⚠️ ' + msg });
const isCvat = (n) => String(n || '').startsWith('cvat-');
const post = (url, body) => ({ method: 'POST', url: url, body: body });

if (!KNOWN.includes(action)) return fail('Невідома або вимкнена дія "' + action + '". Доступні: ' + KNOWN.join(', '));

if (action === 'cost_report') return res({ local: true, data: { servers: servers } });

let srv = null;
if (SERVER_ACTIONS.includes(action)) {
  if (!serverQ) return fail('Вкажіть сервер (параметр server).');
  srv = servers.find(s => String(s.id) === serverQ || s.name === serverQ || (s.public_net && s.public_net.ipv4 && s.public_net.ipv4.ip === serverQ));
  if (!srv) return fail('Сервер "' + serverQ + '" не знайдено. Перевірте назву (list_servers).');
  if (!READ_ONLY.includes(action) && !isCvat(srv.name)) return fail('Заборонено: ' + srv.name + ' не є CVAT-сервером (назва має починатися з cvat-).');
}
if (NEEDS_CONFIRM.includes(action) && !confirmed) {
  return fail('Потрібне явне підтвердження користувача для дії "' + action + '". Поясни наслідки і запитай підтвердження, після чого виклич інструмент ще раз з confirm=yes.');
}

const sid = srv ? srv.id : null;
const B = API + '/servers/' + sid;
let r = null;

if (action === 'server_info') r = { method: 'GET', url: B };
else if (action === 'protect') r = post(B + '/actions/change_protection', { delete: true, rebuild: true });
else if (action === 'unprotect') r = post(B + '/actions/change_protection', { delete: false, rebuild: false });
else if (action === 'rename') {
  if (!/^cvat-[a-z0-9-]{1,50}$/.test(target)) return fail('Нова назва має починатися з cvat- та містити лише a-z, 0-9 і дефіс.');
  r = { method: 'PUT', url: B, body: { name: target } };
}
else if (action === 'shutdown') r = post(B + '/actions/shutdown');
else if (action === 'reset') r = post(B + '/actions/reset');
else if (action === 'rebuild') {
  if (!target) return fail('Вкажіть образ (target): назву, напр. ubuntu-24.04, або ID знімка.');
  r = post(B + '/actions/rebuild', { image: /^[0-9]+$/.test(target) ? Number(target) : target });
}
else if (action === 'enable_rescue') r = post(B + '/actions/enable_rescue', { type: 'linux64' });
else if (action === 'disable_rescue') r = post(B + '/actions/disable_rescue');
else if (action === 'reset_password') r = post(B + '/actions/reset_password');
else if (action === 'list_ssh_keys') return res({ local: true, data: aux });
else if (action === 'add_ssh_key') {
  if (!target) return fail('Вкажіть назву ключа (target).');
  if (!/^(ssh-(ed25519|rsa)|ecdsa-sha2-)/.test(extra)) return fail('Невірний публічний SSH-ключ: extra має починатися з ssh-ed25519, ssh-rsa або ecdsa-sha2-.');
  r = post(API + '/ssh_keys', { name: target, public_key: extra });
}
else if (action === 'create_from_snapshot') {
  // server = назва НОВОГО сервера, target = ID знімка, extra = тариф [локація]
  if (!/^cvat-[a-z0-9-]{1,50}$/.test(serverQ)) return fail('Назва нового сервера (server) має починатися з cvat- та містити лише a-z, 0-9 і дефіс.');
  if (servers.some(s => s.name === serverQ)) return fail('Сервер з назвою ' + serverQ + ' вже існує. Оберіть іншу назву.');
  if (!/^[0-9]+$/.test(target)) return fail('Вкажіть ID знімка (target), лише цифри. Список: list_snapshots.');
  const img = (aux.images || []).find(x => String(x.id) === target);
  if (!img) return fail('Знімок ' + target + ' не знайдено. Перевірте ID (list_snapshots).');
  const ex = extra.toLowerCase().split(/\s+/).filter(Boolean);
  const disk = img.disk_size ? img.disk_size + ' GB' : 'невідомо';
  if (!ex[0]) return fail('Вкажіть тариф (extra): диск тарифу має бути не менше ' + disk + ' (диск сервера, з якого зроблено знімок). Тарифи: list_types.');
  if (!/^[a-z0-9-]{2,20}$/.test(ex[0]) || (ex[1] && !/^[a-z]{3}[0-9]$/.test(ex[1]))) return fail('Невірний тариф або локація: ' + extra);
  r = post(API + '/servers', {
    name: serverQ,
    server_type: ex[0],
    image: Number(target),
    location: ex[1] || 'nbg1',
    start_after_create: false,
    labels: { source: 'snapshot-' + target, created_by: 'cvat-bot' }
  });
  r.snap = { id: img.id, desc: img.description || '', disk: disk };
}
else if (action === 'server_metrics') {
  const types = ['cpu', 'network', 'disk'].includes(target) ? target : 'cpu,network';
  const hours = Math.min(Math.max(parseFloat(extra) || 1, 0.25), 720);
  const end = new Date();
  const start = new Date(end.getTime() - hours * 3600000);
  const step = Math.max(60, Math.round(hours * 3600 / 60));
  r = { method: 'GET', url: B + '/metrics?type=' + types + '&start=' + start.toISOString() + '&end=' + end.toISOString() + '&step=' + step, hours: hours };
}

if (!r) return fail('Дію не реалізовано: ' + action);
return res(Object.assign({ srvName: srv ? srv.name : '' }, r));

const meta = $('Побудувати запит').first().json;
const a = meta.action;
const name = meta.srvName || '';
const done = (m) => [{ json: { success: true, message: m, output: m } }];
const bad = (m) => [{ json: { success: false, message: m, output: m } }];
if (meta.skip) return bad(meta.message);

const r = meta.local ? meta.data : $input.first().json;
if (r && r.error) {
  const e = r.error;
  const msg = (e && e.message) ? e.message : (typeof e === 'string' ? e : JSON.stringify(e));
  if (/resource_unavailable|error during placement/.test(String(msg))) return bad('❌ Hetzner: зараз немає вільних ресурсів для цього тарифу в цій локації. Спробуйте іншу локацію (nbg1, fsn1, hel1) або інший тариф з таким самим диском.');
  return bad('❌ Hetzner: ' + String(msg).slice(0, 400));
}

const gb = (b) => (b / 1e9).toFixed(1) + ' GB';
const act = r && r.action ? ' (action: ' + r.action.status + ')' : '';
const pw = r && r.root_password ? '\n🔑 Root-пароль (тимчасовий, збережіть): ' + r.root_password : '';

if (a === 'cost_report') {
  const price = (s) => {
    const loc = s.location && s.location.name;
    const p = ((s.server_type && s.server_type.prices) || []).find(x => x.location === loc);
    return p ? parseFloat(p.price_monthly.gross) : 0;
  };
  const list = (r.servers || []).map(s => ({ name: s.name, status: s.status, price: price(s), type: String(s.server_type.name).toUpperCase() }));
  const on = list.filter(x => x.status === 'running');
  const off = list.filter(x => x.status === 'off');
  const other = list.filter(x => x.status !== 'running' && x.status !== 'off');
  const sum = (arr) => Math.round(arr.reduce((t, x) => t + x.price, 0) * 100) / 100;
  const lines = [
    '💶 Витрати Hetzner (€/міс, за поточними тарифами):',
    '• Працюють: ' + on.length + ' шт — ' + sum(on) + ' €',
    '• Вимкнені: ' + off.length + ' шт — ' + sum(off) + ' € (вимкнений сервер все одно оплачується)',
    '• Разом: ' + sum(list) + ' €'
  ];
  if (off.length) {
    lines.push('', '⚠️ Вимкнені, але платні:');
    off.forEach(x => lines.push('  – ' + x.name + ' (' + x.type + ') — ' + x.price + ' €'));
    lines.push('Порада: якщо сервер не потрібен, зробіть снепшот і видаліть сервер; відновити можна зі снепшота.');
  }
  if (other.length) lines.push('', 'Інші стани: ' + other.map(x => x.name + ' (' + x.status + ')').join(', '));
  return done(lines.join('\n'));
}
if (a === 'create_from_snapshot') {
  const s = r.server;
  const sn = meta.snap || {};
  return done([
    '✅ Сервер ' + s.name + ' (ID ' + s.id + ') створено зі знімка ' + sn.id + (sn.desc ? ' (' + sn.desc + ')' : '') + act + '.',
    '• Тариф: ' + String(s.server_type.name).toUpperCase() + ', диск ' + s.primary_disk_size + ' GB | Локація: ' + ((s.location || (s.datacenter && s.datacenter.location) || {}).name || '—'),
    '• IPv4: ' + (s.public_net.ipv4 ? s.public_net.ipv4.ip : '—'),
    '• Статус: вимкнено, стара система ще не запускалась.',
    'Далі на вибір:',
    '  – оглянути диск, не запускаючи стару систему: enable_rescue, потім poweron;',
    '  – запустити як є: poweron.',
    '💶 Сервер оплачується, поки існує. Після роботи видаліть його (delete_server; снепшот перед видаленням тут зазвичай не потрібен).'
  ].join('\n') + pw);
}
if (a === 'protect') return done('🔒 Захист від видалення та rebuild увімкнено для ' + name + act + '. Тепер сервер не видалить ні бот, ні консоль, поки захист не знято.');
if (a === 'unprotect') return done('🔓 Захист знято з ' + name + act + '. Тепер сервер можна видалити.');

if (a === 'server_info') {
  const s = r.server;
  const fw = ((s.public_net && s.public_net.firewalls) || []).map(f => f.id).join(', ') || 'немає';
  const lines = [
    'ℹ️ Сервер ' + s.name + ' (ID ' + s.id + ')',
    '• Статус: ' + s.status,
    '• Тариф: ' + String(s.server_type.name).toUpperCase() + ' (' + s.server_type.cores + ' vCPU, ' + s.server_type.memory + ' GB RAM, диск ' + s.primary_disk_size + ' GB)',
    '• IPv4: ' + (s.public_net.ipv4 ? s.public_net.ipv4.ip : '—') + ' | IPv6: ' + (s.public_net.ipv6 ? s.public_net.ipv6.ip : '—'),
    '• Локація: ' + s.location.name + ' (' + s.location.city + ')',
    '• Образ: ' + (s.image ? (s.image.description || s.image.name) : '—'),
    '• Створено: ' + String(s.created).slice(0, 10),
    '• Трафік: вхід ' + gb(s.ingoing_traffic || 0) + ', вихід ' + gb(s.outgoing_traffic || 0) + ' (включено ' + gb(s.included_traffic || 0) + ')',
    '• Rescue: ' + (s.rescue_enabled ? 'увімкнено' : 'вимкнено') + ' | Бекап-вікно: ' + (s.backup_window || 'немає'),
    '• Firewall: ' + fw + ' | Томів: ' + ((s.volumes || []).length) + ' | Захист від видалення: ' + (s.protection && s.protection.delete ? 'так 🔒' : 'ні')
  ];
  return done(lines.join('\n'));
}
if (a === 'rename') return done('✅ Сервер перейменовано на ' + r.server.name + '.\n⚠️ DNS-запис та URL CVAT не змінилися (старий домен залишився).');
if (a === 'shutdown' || a === 'reset' || a === 'disable_rescue') return done('✅ Дію [' + a + '] для ' + name + ' надіслано' + act + '.');
if (a === 'rebuild') return done('✅ Rebuild сервера ' + name + ' запущено' + act + '. Усі дані на диску видалено.\nℹ️ Сервер сам заново встановить CVAT (близько 10–15 хвилин): Hetzner повторно запускає скрипт інсталяції. У чат прийдуть повідомлення про прогрес і НОВІ паролі (старі перестають діяти).' + pw);
if (a === 'enable_rescue') return done('✅ Rescue-режим для ' + name + ' увімкнено' + act + '. Щоб увійти в нього, перезавантажте сервер (reset).' + pw);
if (a === 'reset_password') return done('✅ Пароль root для ' + name + ' скинуто' + act + '.' + pw + '\nℹ️ SSH-вхід root за паролем вимкнено налаштуваннями, тому пароль діє лише в консолі Hetzner.');
if (a === 'list_ssh_keys') {
  const l = (r.ssh_keys || []).map(k => '• ID ' + k.id + ' — ' + k.name + ' (' + k.fingerprint + ')').join('\n');
  return done(l ? '🔑 SSH-ключі в Hetzner:\n' + l : '🔑 SSH-ключів немає.');
}
if (a === 'add_ssh_key') return done('✅ SSH-ключ ' + r.ssh_key.name + ' додано (ID ' + r.ssh_key.id + ').\nℹ️ У нові CVAT-сервери він автоматично не потрапить: для цього його треба додати в скрипт деплою.');
if (a === 'server_metrics') {
  const ts = (r.metrics && r.metrics.time_series) || {};
  const bars = '▁▂▃▄▅▆▇█';
  const lines = [];
  for (const k of Object.keys(ts)) {
    const vals = (ts[k].values || []).map(p => parseFloat(p[1])).filter(v => !isNaN(v));
    if (!vals.length) continue;
    const mx = Math.max.apply(null, vals);
    const avg = vals.reduce((x, y) => x + y, 0) / vals.length;
    const last = vals[vals.length - 1];
    let unit = '';
    let f = (v) => v.toFixed(2);
    if (k === 'cpu') { unit = '%'; }
    else if (k.indexOf('bandwidth') >= 0) { f = (v) => (v / 1e6).toFixed(2); unit = ' MB/s'; }
    else if (k.indexOf('iops') >= 0) { unit = ' IOPS'; }
    const stride = Math.max(1, Math.floor(vals.length / 24));
    let spark = '';
    for (let j = 0; j < vals.length; j += stride) {
      spark += bars[mx > 0 ? Math.min(7, Math.floor(vals[j] / mx * 7)) : 0];
    }
    lines.push('• ' + k + ': середнє ' + f(avg) + unit + ', макс ' + f(mx) + unit + ', зараз ' + f(last) + unit + '\n  ' + spark);
  }
  return done('📈 Метрики ' + name + ' за ' + meta.hours + ' год:\n' + (lines.join('\n') || 'даних немає'));
}
return done('✅ Виконано [' + a + ']' + act);
